137	void RaylibRenderer::beginFrame(const CameraPose& pose) {
138	    camera_.position = {pose.position.x, pose.position.y + 1.7f, pose.position.z};
139	    const float pitchRad = degToRad(pose.pitchDeg);
140	    const float yawRad = degToRad(pose.yawDeg);
141	    const Vector3 dir{std::sin(yawRad) * std::cos(pitchRad), std::sin(pitchRad),
142	                      std::cos(yawRad) * std::cos(pitchRad)};
143	    camera_.target = {camera_.position.x + dir.x, camera_.position.y + dir.y,
144	                      camera_.position.z + dir.z};
145	    camera_.up = {0.f, 1.f, 0.f};
146	    camera_.fovy = 70.f;
147	    camera_.projection = CAMERA_PERSPECTIVE;
148	
149	    // Atmosphere: models carry the fog shader on their materials; wrapping
150	    // the whole 3D pass in BeginShaderMode routes the primitive batch
151	    // (ground plane, slabs, fountain, viewmodel) through the same shader so
152	    // everything hazes consistently. Fog distance needs the camera each
153	    // frame.
154	    if (const Shader* fog = assets_.fogShader()) {
155	        const float eye[3] = {camera_.position.x, camera_.position.y,
156	                              camera_.position.z};
157	        SetShaderValue(*fog, assets_.fogCameraLoc(), eye, SHADER_UNIFORM_VEC3);
158	        BeginMode3D(camera_);
159	        BeginShaderMode(*fog);
160	        return;
161	    }
162	    BeginMode3D(camera_);
163	}
