430	bool RaylibRenderer::worldToScreen(const Vec3& world, Vector2& out) const {
431	    // Reject points behind the camera: GetWorldToScreen would mirror them.
432	    const Vector3 toPoint{world.x - camera_.position.x, world.y - camera_.position.y,
433	                          world.z - camera_.position.z};
434	    const Vector3 forward{camera_.target.x - camera_.position.x,
435	                          camera_.target.y - camera_.position.y,
436	                          camera_.target.z - camera_.position.z};
437	    if (toPoint.x * forward.x + toPoint.y * forward.y + toPoint.z * forward.z <= 0.f) {
438	        return false;
439	    }
440	    out = GetWorldToScreen({world.x, world.y, world.z}, camera_);
441	    return true;
