189	void Assets::loadCharacter(const std::string& stem) {
190	    const std::string path = charDir_ + "/" + stem + ".glb";
191	    if (!std::filesystem::exists(path)) {
192	        std::cerr << "[llm_npc] missing character: " << path << "\n";
193	        return;
194	    }
195	    CharacterAsset character;
196	    character.model = LoadModel(path.c_str());
197	    if (character.model.meshCount == 0) {
198	        std::cerr << "[llm_npc] failed to load character: " << path << "\n";
199	        return;
200	    }
201	
202	    // The packs mix skinned body meshes with unskinned attachment meshes
203	    // (held items). raylib 5.5's CPU skinning dereferences boneWeights
204	    // unconditionally and crashes on the unskinned ones, so compact them
205	    // out — v1 characters simply don't show hand props.
206	    int kept = 0;
207	    for (int i = 0; i < character.model.meshCount; ++i) {
208	        if (character.model.meshes[i].boneWeights != nullptr) {
209	            character.model.meshes[kept] = character.model.meshes[i];
210	            character.model.meshMaterial[kept] = character.model.meshMaterial[i];
211	            ++kept;
212	        } else {
213	            UnloadMesh(character.model.meshes[i]);
214	        }
215	    }
216	    character.model.meshCount = kept;
217	    if (kept == 0) {
218	        std::cerr << "[llm_npc] character had no skinned meshes: " << path << "\n";
219	        UnloadModel(character.model);
220	        return;
221	    }
222	
223	    // Characters fog too. CPU skinning is unaffected: it writes animated
224	    // vertices into the mesh before drawing, and the fog shader consumes
225	    // only the standard position/texcoord/color attributes.
226	    if (fogLoaded_) {
227	        for (int i = 0; i < character.model.materialCount; ++i) {
228	            character.model.materials[i].shader = fogShader_;
229	        }
230	    }
231	
232	    character.clips = LoadModelAnimations(path.c_str(), &character.clipCount);
233	    for (int i = 0; i < character.clipCount; ++i) {
234	        const std::string name = character.clips[i].name;
235	        if (name == "Idle") character.idle = i;
236	        else if (name == "Walking_A") character.walk = i;
237	        else if (name == "Cheer") character.gesture = i;
238	        else if (name == "Death_A_Pose") character.death = i;
239	    }
240	    if (stem == "Knight") knightIndex_ = static_cast<int>(characters_.size());
241	    characters_.push_back(character);
242	}
