245	    if (characters_.empty()) return nullptr;
246	    if (police && knightIndex_ >= 0) return &characters_[static_cast<std::size_t>(knightIndex_)];
247	    return &characters_[static_cast<std::size_t>(variantSeed) % characters_.size()];
248	}
