250	bool Assets::loadCityModel(const std::string& stem) {
251	    const std::string path = cityDir_ + "/" + stem + ".gltf";
252	    if (!std::filesystem::exists(path)) {
253	        std::cerr << "[llm_npc] missing model: " << path << " (using fallback shape)\n";
254	        return false;
255	    }
256	    Model model = LoadModel(path.c_str());
257	    if (model.meshCount == 0) {
258	        std::cerr << "[llm_npc] failed to load model: " << path << "\n";
259	        return false;
260	    }
261	    // Atmosphere: every material renders through the shared fog shader.
262	    // (UnloadModel leaves material shaders alone — raylib treats them as
263	    // user-owned precisely so they can be shared; the destructor unloads
264	    // fogShader_ exactly once.)
265	    if (fogLoaded_) {
266	        for (int i = 0; i < model.materialCount; ++i) {
267	            model.materials[i].shader = fogShader_;
268	        }
269	    }
270	    models_.emplace(stem, model);
271	    return true;
272	}
273	
274	const Assets::SizeSpec& Assets::sizeSpecFor(const Building& building) const {
275	    static const SizeSpec fill{};  // Mode::Fill — the default contract
276	    const auto it = sizeSpecs_.find(building.id);
277	    return it != sizeSpecs_.end() ? it->second : fill;
278	}
279	
280	const Model* Assets::modelForBuilding(const Building& building) const {
281	    if (!loaded_) return nullptr;
282	    const auto curated = curated_.find(building.id);
283	    const std::string stem =
284	        curated != curated_.end()
285	            ? curated->second
286	            : genericBuildings_[stableHash(building.id) % genericBuildings_.size()];
287	    const auto it = models_.find(stem);
288	    return it != models_.end() ? &it->second : nullptr;
289	}
290	
291	const Model* Assets::prop(const std::string& stem) const {
292	    const auto it = models_.find(stem);
293	    return it != models_.end() ? &it->second : nullptr;
294	}
295	
296	}  // namespace llm_npc
