11	// Part categories for the character creator. Extending the system is a
12	// data change: add an enum value, a CategorySpec row (who it attaches to,
13	// via which socket), and catalog parts that declare that socket.
14	enum class PartCategory { Body, Head, Eyes, Hair };
15	constexpr int kPartCategoryCount = 4;
16	
17	// How a category attaches into the assembly: every non-root category names
18	// its parent category and the SOCKET NAME it snaps to. The socket's
19	// position is authored on each parent part (in that part's local space) —
20	// there is deliberately no per-pair offset table anywhere.
21	struct CategorySpec {
22	    PartCategory category;
23	    PartCategory parent;      // ignored for the root (Body)
24	    const char* socket;       // "" for the root
25	};
26	
27	// One authorable part. `localSize` is the part's bounding box with the
28	// anchor at the bottom-center (the same feet-on-ground convention world
29	// positions use); `sockets` are child attach points relative to that
30	// anchor. `styleTag` gates combinations: "round"/"blocky" families plus
31	// "any" parts that fit either.
32	struct PartDef {
33	    std::string id;
34	    PartCategory category = PartCategory::Body;
35	    std::string styleTag;
36	    Vec3 localSize{};
37	    std::unordered_map<std::string, Vec3> sockets;
38	};
39	
40	// A named flat-color palette (RGB 0-255) the renderer maps onto recipes.
41	struct PartPalette {
42	    std::string id;
43	    unsigned char skin[3];
44	    unsigned char hair[3];
45	    unsigned char outfit[3];
46	};
47	
48	// The look half of a created character: one part id per category plus a
49	// palette. Fully independent from the persona record by design.
50	struct CharacterLook {
51	    std::string partIds[kPartCategoryCount];  // indexed by PartCategory
52	    std::string paletteId;
53	
54	    std::string& part(PartCategory c) { return partIds[static_cast<int>(c)]; }
55	    const std::string& part(PartCategory c) const {
56	        return partIds[static_cast<int>(c)];
57	    }
58	
59	    // Compact JSON for storage; fromJson returns false on malformed input.
60	    std::string toJson() const;
61	    static bool fromJson(const std::string& json, CharacterLook& out);
62	};
63	
64	// One placed part of a finished assembly: its anchor position in assembly
65	// space (unscaled part-local units; the renderer applies the single size
66	// contract scale afterwards).
67	struct PlacedPart {
68	    const PartDef* part = nullptr;
69	    Vec3 position{};
70	};
71	
72	// A resolved look: every category placed, total height measured so ONE
73	// uniform scale can satisfy the character height contract.
74	struct AssembledLook {
75	    bool ok = false;
76	    std::string error;             // set when !ok
77	    std::vector<PlacedPart> parts; // assembly order: parents before children
78	    float height = 0.f;            // unscaled; contract scale = target / height
79	};
